syntax = "proto3";

package analytics.v1;

message TelemetryEvent {
  string event_id = 1;
  uint64 timestamp_ns = 2;

  enum EventSeverity {
    INFO = 0;
    WARNING = 1;
    CRITICAL = 2;
  }

  EventSeverity severity = 3;
  map<string, string> metadata = 4;
  bytes raw_payload = 5;
}

