struct NetworkPacket {
  id @0 :UInt64;
  timestamp @1 :Int64;
  srcIp @2 :Text;
  dstIp @3 :Text;

  payload :union {
    rawBytes @4 :Data;
    httpPayload @5 :HttpMetadata;
  }
}

struct HttpMetadata {
  method @0 :Text;
  statusCode @1 :UInt16;
  headers @2 :List(HeaderPair);
}

struct HeaderPair {
  key @0 :Text;
  value @1 :Text;
}

